use crate::{Result,CrawlProfile,authentication::Session};
pub fn validate(profile:&CrawlProfile,session:Option<&Session>)->Result<()> {
 if !["automatic","direct","manual"].contains(&profile.proxy_mode.as_str()){return Err("Proxy mode must be automatic, direct or manual".into())}
 if profile.proxy_bypass.len()>4096||profile.proxy_bypass.chars().any(char::is_control)||profile.proxy_bypass.split(',').filter(|value|!value.trim().is_empty()).count()>100||profile.proxy_bypass.split(',').any(|value|value.trim().len()>256||value.trim().chars().any(char::is_whitespace)||value.contains("://")||value.contains(['@','?','#','\\'])){return Err("Proxy bypass accepts at most 100 comma-separated hosts/domain suffixes/IP ranges, 256 bytes each and 4096 bytes total".into())}
 if !profile.proxy_url.is_empty(){crate::authentication::normalize_origin(&profile.proxy_url).map_err(|_|"Proxy origin must not contain credentials or a path")?;}
 if profile.proxy_mode!="automatic"&&profile.rendering.enabled{return Err("Explicit proxy/direct settings currently require HTTP-only crawling; disable JavaScript rendering".into())}
 if profile.proxy_mode!="manual"{if profile.proxy_auth_required||session.is_some(){return Err("Proxy credentials require manual proxy mode".into())}return Ok(())}
 crate::authentication::normalize_origin(&profile.proxy_url).map_err(|_|"Manual proxy requires an HTTP(S) origin without path, credentials, query or fragment")?;
 if profile.proxy_auth_required{crate::authentication::validate_configuration(&profile.proxy_url,session,false).map_err(|error|format!("Proxy authentication: {error}"))?}else if session.is_some(){return Err("Enable proxy authentication explicitly before supplying proxy credentials".into())}Ok(())
}
pub(crate) fn build(profile:&CrawlProfile,session:Option<&Session>)->Result<reqwest::Proxy>{validate(profile,session)?;let origin=crate::authentication::normalize_origin(&profile.proxy_url)?;let mut proxy=reqwest::Proxy::all(&origin).map_err(|_|"Could not configure the manual HTTP(S) proxy")?.no_proxy(reqwest::NoProxy::from_string(&profile.proxy_bypass));if let Some(session)=session{let header=session.header_for(&origin).ok_or("Proxy session origin differs from the selected proxy")?;proxy=proxy.custom_http_auth(header)}Ok(proxy)}
#[cfg(test)]mod tests{use super::*;
 #[test]fn modes_urls_bypass_and_missing_credentials_are_validated(){let mut p=CrawlProfile::default();assert!(validate(&p,None).is_ok());p.proxy_mode="direct".into();assert!(validate(&p,None).is_ok());p.proxy_url="http://user:secret@localhost:9999".into();assert!(validate(&p,None).is_err());p.proxy_url.clear();p.proxy_mode="manual".into();for url in ["socks5://localhost:9999","http://u:p@localhost:9999","http://localhost:9999/path","localhost:9999"]{p.proxy_url=url.into();assert!(validate(&p,None).is_err())}p.proxy_url="http://localhost:9999".into();p.proxy_bypass="localhost,.example.test,127.0.0.0/8,::1".into();assert!(build(&p,None).is_ok());p.proxy_bypass="example.test\r\n".into();assert!(validate(&p,None).is_err());p.proxy_bypass.clear();p.proxy_auth_required=true;assert!(validate(&p,None).is_err());let session=Session::new("http://localhost:9999","user","owned-secret").unwrap();assert!(build(&p,Some(&session)).is_ok());let other=Session::new("http://localhost:9998","user","owned-secret").unwrap();assert!(validate(&p,Some(&other)).is_err());p.rendering.enabled=true;assert!(validate(&p,Some(&session)).is_err());}
}
